return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-10-02T10:28:39+00:00','po-revision-date'=>'2026-10-02T10:28:39+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'Premješta biblioteku medija ovog web-mjesta u Zinn® objektnu pohranu i poslužuje je putem CDN-a. Konfigurirano s Vaše Zinn® nadzorne ploče — pristupni se ključ nikada ne unosi u WordPress.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Pohranjeno. Upišite novu vrijednost kako biste je zamijenili.','Filter this list…'=>'Filtrirajte ovaj popis…','Filter this list'=>'Filtriraj ovaj popis','Nothing matches that filter.'=>'Ništa ne odgovara tom filteru.','Add a row'=>'Dodaj redak','Remove this row'=>'Uklonite ovaj redak','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pregled','Overview'=>'Pregled','Copied'=>'Kopirano','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® priključak na ovom web-mjestu i radi li.','No connection is needed for this plugin.'=>'Za ovaj priključak nije potrebno povezivanje.','Open settings'=>'Otvori postavke','You do not have permission to change these settings.'=>'Nemate dopuštenje za promjenu ovih postavki.','Settings sections'=>'Odjeljci postavki','Support'=>'Podrška','Save changes'=>'Spremi promjene','Tools'=>'Alati','Export settings'=>'Izvezi postavke','Reset to defaults'=>'Vrati na zadano','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća sve postavke ovog priključka na zadane vrijednosti. Želite li nastaviti?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvezite datoteku postavki','Import'=>'Uvezi','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, tokene ili API ključeve — morat ćete ih ponovno unijeti na novom web-mjestu.','Settings saved.'=>'Postavke su spremljene.','Every setting on this plugin is back to its default.'=>'Sve postavke ovog priključka vraćene su na zadane vrijednosti.','Done.'=>'Dovršeno.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Tu datoteku nije bilo moguće pročitati. Odaberite datoteku postavki izvezenu iz Zinn® priključka.','That file is too large to be a settings export.'=>'Ta datoteka je prevelika da bi bila izvoz postavki.','That file is not a Zinn® settings export.'=>'Ta datoteka nije izvoz postavki za Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Ta je datoteka izvezena iz drugog priključka (%s), pa bi se njezinim uvozom ovdje spremile postavke koje ovaj priključak ne razumije.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d postavka je uvezena. Lozinke i API ključevi nikada nisu uključeni u izvoz, stoga ih unesite ponovno.' . "\0" . '%d postavki uvezeno. Lozinke i API ključevi nikada se ne nalaze u izvozu, pa ih unesite ponovno.' . "\0" . '%d postavki uvezeno. Lozinke i API ključevi nikada se ne nalaze u izvozu, pa ih unesite ponovno.','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® nije vratio token. Na ovom web-mjestu ništa nije promijenjeno.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'Ovo web-mjesto više nije povezano s rasterećenjem medija Zinn®. Novi prijenosi ostat će na ovom poslužitelju. Ponovno ga uparite s Vaše nadzorne ploče Zinn Digital®.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® je odgovorio s HTTP %d.','Disconnected by Zinn Digital®.'=>'Prekinula usluga Zinn Digital®.','Connected'=>'Povezano','Connecting…'=>'Povezivanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahtijeva pozornost','Not connected'=>'Nije povezano','Running on your own account'=>'Izvodi se na vašem vlastitom računu','We could not check this'=>'Nismo uspjeli ovo provjeriti','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostičko izvješće i mi ćemo pogledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Zadnja provjera prije %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošaljite ovo podršci za Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Upravo je to ono što će biti poslano — ništa drugo i ništa skriveno. Vaše lozinke, tokeni i API ključevi nisu u tome.','The diagnostics report that will be sent'=>'Dijagnostičko izvješće koje će biti poslano','Copy to clipboard'=>'Kopiraj u međuspremnik','Send this report to Zinn® support'=>'Pošaljite ovo izvješće podršci za Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otvaramo korisnički zahtjev za Vas i odgovaramo e-poštom. Ako ga radije ne biste poslali, kopirajte ga iznad i sami zalijepite u zahtjev.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo uspjeli doći do Zinn Digital® s ovog poslužitelja (%s). Kopirajte gore navedeni izvještaj i umjesto toga otvorite prijavu — ništa u vašim postavkama nije pogrešno.','Sent. Zinn® support has your report and will reply by email.'=>'Poslano. Podrška za Zinn® zaprimila je vašu prijavu i odgovorit će vam e-poštom.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Poslano. Podrška za Zinn® zaprimila je Vašu prijavu — referenca %s — i odgovorit će Vam e-poštom.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko prijava u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno — prethodne su stigle.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutačno nije mogao prihvatiti izvješće — problem je na našoj strani, a ne na Vašoj. Pokušajte ponovo uskoro ili kopirajte gore navedeno izvješće u tiket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izvještaj je odbijen (HTTP %d). Kopirajte ga iznad i otvorite tiket, navodeći taj broj.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički priručnici','Read the %s user guide'=>'Pročitajte korisnički vodič za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, svakodnevne sigurnosne kopije, besplatna migracija i upravljačka ploča stvorena za ljude koji vode više od jedne web-stranice.','The Zinn® marketplace'=>'Tržnica Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte etablirane web-stranice, domene i postavljanja poveznica, pri čemu se novac sigurno čuva dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — angažirajte ljude koji se time profesionalno bave','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih stručnjaka: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i omogućite im slanje ponuda.','Media Offload'=>'Rasterećenje medija','Connection'=>'Veza','What gets moved'=>'Što se premješta','How media is served'=>'Način posluživanja medija','Move a batch now'=>'Premjesti grupu sada','Media already moved is never affected by a change here — its address does not change.'=>'Promjena ovdje nikada ne utječe na već premještene medije — njihova se adresa ne mijenja.','New uploads'=>'Nova prijenosa','Move new uploads to Zinn® storage as they arrive'=>'Premjestite nova prijenosa u Zinn® pohranu čim stignu','Existing media'=>'Postojeći mediji','Keep moving the media library that is already here'=>'Nastavite premještati biblioteku medija koja je već ovdje','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'Nekoliko datoteka na sat, u pozadini, nastavljajući tamo gdje je stalo. Isključivanje ove opcije privremeno zaustavlja postupak; ništa što je već premješteno ne vraća se natrag.','Files per hourly pass'=>'Datoteka po satnom prolazu','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'Svaki privitak sastoji se od nekoliko datoteka i svaka je potpuno učitavanje. Povećajte ovo na brzom poslužitelju s izdašnim ograničenjem izvršavanja; smanjite ako se prolazi prekidaju.','Leave files smaller than'=>'Ostavite datoteke manje od','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'Kilobajti. Mala ikona košta više u dodatnoj vezi nego što štedi na disku, pa rijetko postoji razlog za njezino premještanje. Postavite na 0 kako biste premjestili sve.','Never move these types'=>'Nikada ne premještajte ove vrste','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'Korisno kada priključak čita datoteku izravno s diska — font, PDF koji kreator obrazaca ovjerava, zvučnu datoteku unutar koje preglednik pretražuje.','These two are the ones to be careful with — read each description before changing it.'=>'S ova dva trebate biti oprezni — pročitajte svaki opis prije nego što ga promijenite.','Serve from Zinn® storage'=>'Isporučujte iz pohrane Zinn®','Point image and file addresses at Zinn® storage'=>'Usmjerite adrese slika i datoteka na Zinn® pohranu','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'Isključeno, datoteke se prenose, ali se i dalje poslužuju s ovog poslužitelja — što je sigurno stanje dok provjeravate je li sve stiglo. Uključeno, posjetitelji se poslužuju iz pohrane i ovaj poslužitelj prestaje prenositi promet.','Free the disk space'=>'Oslobodite prostor na disku','Delete the local copy once every size has uploaded'=>'Izbrišite lokalnu kopiju nakon što se učitaju sve veličine','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'To je svrha rasterećenja, a ujedno i nepovratni dio. Ostavite to isključeno dok se ne uključi „Poslužuj iz Zinn® pohrane” i dok ne provjerite svoje web-mjesto — lokalna kopija jedina je stvar koja vas spašava ako je nešto propušteno.','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'Brisanje lokalnih kopija ne može se poništiti s ovog zaslona. Najprije napravite sigurnosnu kopiju — priključak Zinn® Connector može to učiniti za vas.','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'Ovo web-mjesto još nije povezano sa Zinn® pohranom, pa nema mjesta na koje biste premjestili medije.','%d attachment moved.'=>'%d privitak premješten.' . "\0" . 'Premješteno privitaka: %d.' . "\0" . 'Premješteno privitaka: %d.','This site is not connected to Zinn® storage.'=>'Ovo web-mjesto nije povezano sa Zinn® pohranom.','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'Sve je u redu — samo još nije upareno. Medijski zapisi ostaju na ovom poslužitelju dok se to ne učini.','Connected, but the last upload failed.'=>'Povezano, ali zadnji prijenos nije uspio.','Try a batch now'=>'Isprobajte paket sada','Connected. Every attachment has been moved.'=>'Povezano. Svaki je privitak premješten.','Connected. %1$s of %2$s attachments still on this server.'=>'Povezano. %1$s od %2$s privitaka još uvijek je na ovom poslužitelju.','Moved so far'=>'Dosad premješteno','%1$s files, %2$s'=>'%1$s datoteka, %2$s','Still on this server'=>'I dalje na ovom poslužitelju','%1$s of %2$s attachments'=>'%1$s od %2$s privitaka','Served from'=>'Posluženo s','this server'=>'ovaj poslužitelj','Connect this site'=>'Povežite ovu web-stranicu','Open your Zinn Digital® dashboard, choose this site, open Files & databases, and press “Get a pairing code” under Images & video CDN. Paste the code below.'=>'Otvorite svoju Zinn Digital® upravljačku ploču, odaberite ovo web-mjesto, otvorite Datoteke i baze podataka te pritisnite „Dohvati kôd za uparivanje” ispod CDN za slike i videozapise. Zalijepite kôd u nastavku.','Pairing code'=>'Kôd za uparivanje','Disconnect this site'=>'Odspojite ovu web-stranicu','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'Novi prijenosi ostat će na ovom poslužitelju. Već premješteni medijski sadržaji nastavljaju raditi — njihova se adresa ne mijenja.','You do not have permission to manage this site.'=>'Nemate dopuštenje za upravljanje ovim web-mjestom.','Paste the pairing code from your Zinn Digital® dashboard.'=>'Zalijepite kôd za uparivanje s vaše Zinn Digital® nadzorne ploče.','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'Povezano. Nova učitavanja od sada će se pohranjivati na Zinn Digital®, a Vaši postojeći mediji premjestit će se u pozadini.','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'Veza je prekinuta. Već premješteni medijski sadržaji nastavljaju raditi; nova učitavanja ostaju na ovom poslužitelju.','That file could not be read from this server, so nothing was uploaded.'=>'Ta se datoteka nije mogla pročitati s ovog poslužitelja, pa ništa nije preneseno.','This site could not stream the upload, so nothing was sent.'=>'Ovo web-mjesto nije moglo prenositi učitavanje, pa ništa nije poslano.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'Ova datoteka je veličine %1$s, a PHP ove stranice nema cURL, pa je najveća veličina koju može prenijeti %2$s.','The upload could not be completed.'=>'Prijenos se nije mogao dovršiti.','Storage refused the upload (HTTP %d).'=>'Pohrana je odbila prijenos (HTTP %d).','Style preset'=>'Zadano oblikovanje stila','A starting point. Anything below overrides it.'=>'Polazna točka. Sve ispod je prepisuje.','Use my own colours and sizes'=>'Upotrijebite moje vlastite boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Ostavite ovo isključeno i predlošci će se koristiti točno onako kako jesu.','See the Zinn Digital® release notes.'=>'Pogledajte napomene o izdanju za Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usluga ažuriranja Zinn® nije izdala poveznicu za preuzimanje ovog ažuriranja. Provjerite može li ovo web-mjesto pristupiti platformi Zinn®, a zatim pokušajte ponovno.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ažuriranje se nije moglo preuzeti s usluge ažuriranja Zinn® (%s). Pokušajte ponovo za nekoliko minuta.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.']];